// ---------------------------------------------------------------- arm library (rig: sx<0 forward, sz>0 out, el<0 bend)
const A = (sx, sz, el, twist = 0, free = 0) => ({ sx, sz, el, twist, free });
const REST = A(0.03, 0.07, -0.18, 0, 1);
const UP_A = A(-2.8, 0.35, -0.35), UP_B = A(-2.8, 0.35, -0.35);
const MOUTH_A = A(-1.25, 0.32, -2.25, 0.75), MOUTH_B = A(-1.25, 0.32, -2.25, -0.75);     // hands over the mouth
const HEAD_A = A(-2.3, 0.75, -2.0, 0.6), HEAD_B = A(-2.3, 0.75, -2.0, -0.6);             // hands on the head (despair)
const HOLD_A = A(-0.6, 0.15, -1.45, 0.3), HOLD_B = A(-0.55, 0.15, -1.45, -0.3);
const CHALK_B = A(-2.35, 0.25, -0.45, -0.3);                                              // arm up at the board
const WASH_B = A(-0.85, 0.2, -0.5, -0.2);                                                 // holding a hose/sponge low
const mixArm = (a, b, k) => ({ sx: lerp(a.sx, b.sx, k), sz: lerp(a.sz, b.sz, k), el: lerp(a.el, b.el, k), twist: lerp(a.twist || 0, b.twist || 0, k), free: lerp(a.free ?? 0, b.free ?? 0, k) });
/** THE gesture: both forearms forward, palms up, bobbing up/down in opposition (a two-pan scale). k 0..1 = how much. */
const RATE = 2.4;
function seesaw(t, ph = 0, k = 1, big = 1) {
  const s = Math.sin((t * RATE + ph) * 2 * PI) * big;
  return {
    a: mixArm(REST, A(-0.55 + 0.38 * s, 0.2, -1.4 - 0.45 * s, 0.15), k),
    b: mixArm(REST, A(-0.55 - 0.38 * s, 0.2, -1.4 + 0.45 * s, -0.15), k),
  };
}
const seatY = (top) => -0.375 + (top - 0.42);

const SKINS = [0xf1c3a1, 0xe2ad8c, 0xc98e6a, 0x9a6447, 0x6e4430, 0xf3d0b5, 0xd9a37f];
